import{_ as s,O as i,o as a,c as r,a as o,i as n,f as c}from"./chunks/framework.fmIt2z2h.js";const g=JSON.parse('{"title":"D.19　政治思想、制度愿景与规范分歧","description":"","frontmatter":{"title":"D.19　政治思想、制度愿景与规范分歧","xkChars":644,"xkLessons":{"D.19":{"title":"D.19　政治思想、制度愿景与规范分歧","lead":"一种制度可以长期稳定，仍有理由受到规范批评；一种愿景也可以揭示新可能，却不因此成为历史必然。政治思想比较要公开具体权利、决定权和过渡成本，不让框架替人作政治选择。","explanation":["原文定位：第4821—4836行；原文锚点 section-d-19；短引文：‘稳定、效率与值得维持可以真实分离，不必把规范批评转换成必然失败预言。’。本题源切片逐字另附于source-slice.md，讲解与原文分开。","自由主义、共和主义、民主思想、保守主义、社会主义诸传统、无政府主义、民族主义与去殖民批评，围绕自由平等秩序共同体财产权威提出不同问题。每个标签内部都有争论，不能用一个简化立场代表全部。应说明比较的是哪位作者、哪个时期、何种具体主张及机制，而不是由框架预排传统总名次。","权利规则、可争辩和可撤换的权力、参与效力、变迁与现状成本、生产资源控制、地方协作与跨地域制度，需要分别描述。某传统着重某问题，不意味着其他传统完全不讨论它。相称比较不应只给喜欢的传统保留复杂性，再把对方简化为最弱口号。","名义所有、共同身份和地方自治都不能直接证明实际控制与分配。共同名义下可能有集中决定，地方范围内也可能存在不可替代的控制关口。应追踪谁能提名、设议程、取得信息、表决、执行、撤换和复核，而不是由所有权名称或共同体口号自动填入每个人的决定权。","一个不可替代关口就可能形成重要控制，不必所有环节都被同一方垄断。例如人们可以自由讨论与投票，但若唯一实施入口由某人无复核地把持，选择仍可能无法变为现实。实际控制是具体通道问题，分散权力不能只靠统计会议人数或把组织分成许多小组来证明。","愿景有助提出尚未实现的制度可能，反乌托邦能揭示控制风险；二者都不自动预测历史终点。条件推论必须说明如果什么成立会怎样，已观察结果则要有相应材料。不能因一种叙事有启发性就把未来写成已知，也不能把批评中的极端构造直接等同对现实制度的经验判决。","具体制度比较要固定对象、时段与人群，说明谁有何权利、谁作决定、谁承担过渡成本。维持现状同样可能有成本，改革也可能带来风险；不能只核一边。对不能迁移或退出的人，更要保留实际位置和后果，不能把总效率替代受影响者的具体损益与权利。","框架自身authorized、applied和治理状态只是其内部承诺，不能冒充外部法律效力。一个模块获得内部许可，不等于某项公共行动已由法律授权；框架也不能把所有公共决定强制改造成逐人一致同意制度。外部制度有自己的事项、代表和问责机制，需按其具体规则评价。","反过来，有外部法律依据不自动证明规范正当。法律效力与值得支持是不同问题，思想比较可以帮助公开价值冲突，而不能以经验或程序名义消除真正分歧。稳定和效率也不提供全部正当性：即使一种受到批评的安排没有迅速失败，独立的权利或平等理由仍可提出。","合法制度代表不需要补造每个被代表者都曾作出私人同意的故事，但仍须面对代表事项、范围、形成程序和问责。形式上当选不表示每项行动都可不受限制，也不表示反对者已经心服口服。不能在一端要求无法满足的逐人一致，在另一端又把代表资格扩成不受检验的无限权力。","八个入口依次是Locke Mill Berlin Rawls等自由主义谱系，共和与民主，Burke等保守主义，社会主义马克思主义社会民主，无政府互助地方自治，民族主义国家认同法西斯主义，后殖民去殖民依附，以及乌托邦反乌托邦历史终结。并列不是规范等同，更不抹掉压迫或排除的具体问题。最强反方担心不排名就是相对主义；回应是可以明确提出权利和保护理由并作具体比较，只是不拿通用框架替代全部政治判断。"],"distinctions":[{"leftTitle":"政治传统标签","leftText":"广泛研究与争论入口。","rightTitle":"具体制度主张","rightText":"须核作者文本、机制与内部差异，不以标签总代。"},{"leftTitle":"名义共同所有或自治","leftText":"名称与制度表述。","rightTitle":"实际控制分配","rightText":"追踪具体决定关口和实施资源。"},{"leftTitle":"愿景与反乌托邦","leftText":"提出可能与风险的理解工具。","rightTitle":"历史预测","rightText":"需要条件和经验支持，不自动成为终点预言。"},{"leftTitle":"框架内部许可","leftText":"authorized/applied限定自身采用承诺。","rightTitle":"法律效力与正当性","rightText":"二者也各自独立，不互相冒充。"},{"leftTitle":"制度代表","leftText":"按具体规则形成有限事项代表资格。","rightTitle":"私人全体一致","rightText":"不得为证明代表而虚构每个人同意，仍需范围问责。"}],"boundaries":["不替用户或群体作政治选择，不按单一框架为所有政治传统总排名。","规范批评不依赖虚构必然低效崩溃；合法稳定有效也不自动正当。","内部治理状态不能越权充当外部法律许可，不强行改造所有公共决定为一致同意。","不由地方自治、共同身份或名义所有推断人人实际控制。","案例仅为历史制度文本的有限阅读，不提供当代个案法律意见或评价整个国家制度优劣。"],"questions":["为什么不作总排名仍能进行规范批评？","反乌托邦为何不能直接当历史预测？","制度代表为何不必虚构私人一致同意？","实际控制如何超出名义所有？"],"diagramPath":"/reading-assets/S-D-19/figures/section-d-19.png","caseLinks":[{"title":"真实历史制度文本：代表机构的权限与表决门槛","href":"https://www.archives.gov/founding-docs/constitution-transcript"}],"caseNotes":[{"title":"真实历史制度文本：代表机构的权限与表决门槛","text":"美国国家档案馆公布的1787年宪法原件转录中，Article I Section1把所授立法权置于两院国会；Section5规定各院法定人数及议事规则；Section7另列总统异议与两院复议的门槛。这说明可以逐事项读代表、法定人数和复议安排，不能把这些制度文本改写成每位公民对每项决定的私人一致同意。","sourceLabel":"U.S. National Archives，Constitution原件转录，页面审阅2026-09-08","sourceUrl":"https://www.archives.gov/founding-docs/constitution-transcript","sourceLocator":"页面Note原件转录性质；Article I §§1、5、7（行50、58、87—91、98—102）","boundary":"只核原件转录所载安排，不作今日全部宪法法律解释；原文含后来修订处，页面以链接提示。程序存在不证明历史排除不存在、现实均实现或制度整体正当。","href":"https://www.archives.gov/founding-docs/constitution-transcript"}],"sourceRefs":[{"section":"D.19","start_line":4821,"end_line":4836,"startLine":4821,"endLine":4836}],"outputId":"section-d-19","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","argumentSteps":["按具体作者时期主张和机制比较，保留内部争议与相称对照。","逐项列权利、议题信息表决实施撤换复核，辨名义归属与实际控制。","固定对象时段人群，并列现状和过渡成本、可退出与不能退出者。","区分愿景启发、条件推论和已观察结果，不预言必然历史终点。","把内部authorized/applied、外部法律效力和规范正当分开，制度代表按范围问责而不补造私人一致。"],"teachingExamples":[{"title":"教学构造：只控制实施也可形成关口","text":"假想协会成员可提案、自由讨论和表决，但只有一名人员能提交唯一可执行指令，且其拒绝无复核替代。即使其他环节分散，这个不可替代实施关口仍能阻断决定。分散权力须核全链，不要求全链皆被垄断才承认控制。","assumptions":"协会与权限完全虚构，不影射现实政治组织。","boundary":"具体控制程度仍需替代路径和制约材料；不提供夺取或规避权限的操作。"},{"title":"教学构造：稳定不抹去规范批评","text":"假想某安排长期维持且成本较低，却排除了部分人的基本参与位置，违反了本例中明确辩护的平等原则。可以承认稳定与效率的既有材料，同时提出规范批评，不必补写其一定即将崩溃。","assumptions":"稳定效率与规范条件均设定，仅展示逻辑可分。","boundary":"不指认现实群体或预言政治变化，规范原则本身仍应公开论证。"},{"title":"教学构造：内部通过不等外部授权","text":"假想研究团队把分析模块记为authorized并满足applied内部条件，随后打算据此改变另一机构的资源分配。内部状态不能授予外部决定权；还须核真实机构权限、受影响者和适用规范。","assumptions":"虚构采用场景，未操作任何实际分配。","boundary":"有外部许可也不自动结束正当性讨论。"},{"title":"教学构造：代表范围与反对可以并存","text":"假想组织按有效程序选出事务代表，部分成员投反对票。无需编造这些人私下其实都同意，代表可以在明确范围内履职；但仍要说明议题权限、可撤换与问责，不能把当选变成对所有生活事项的无限授权。","assumptions":"程序有效与范围明确为教学假设，无真实选举。","boundary":"不判断任何具体制度合法性，也不要求反对者放弃批评。"}],"counterexamples":[{"identity":"source_counterexample","text":"一种安排被规范批评，所以必然短期崩溃。","effect":"规范与经验预测分别承担论证责任，稳定并不取消批评。","sourceIds":["theory"]},{"identity":"source_counterexample","text":"只有一个环节被控制，其他都开放，所以不存在重要控制。","effect":"不可替代关口可阻断全链，需查替代复核而非只数开放环节。","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"内部applied成立，所以任何公共行动都已获法律许可。","effect":"内部承诺与外部法律权力不同，不能跨域授权。","sourceIds":["theory"]}],"questionAnswers":[{"question":"为什么不作总排名仍能进行规范批评？","answer":"可公开权利和保护理由、比较具体机制与后果，而不把一套通用指标当全部政治答案。","basis":"本节原文及上述公开推导"},{"question":"反乌托邦为何不能直接当历史预测？","answer":"它可能是风险构造与概念探讨，现实发生还需条件和证据。","basis":"本节原文及上述公开推导"},{"question":"制度代表为何不必虚构私人一致同意？","answer":"代表资格来自具体制度程序和事项范围，不等每个人内心认同；问责仍必要。","basis":"本节原文及上述公开推导"},{"question":"实际控制如何超出名义所有？","answer":"决定议题、资源、实施与复核的真实关口可能与所有权名称不同。","basis":"本节原文及上述公开推导"}],"figures":[{"path":"/reading-assets/S-D-19/figures/section-d-19.png","alt":"传统内部有争论，具体主张机制条件，不预排总名次；提名议题信息表决，实施撤换复核，单一关口也可控制；对象时段人群固定，现状与过渡成本，不能退出者仍保留；愿景揭示可能，反乌托邦揭示风险，不自动预言终点；内部authorized/applied，外部法律效力，规范正当三层；稳定效率可与正当分离，代表范围与问责须核，不补造私人一致。作者依D.19绘制；组织例均为教学构造，历史文本不替代当代法律核查。","caption":"作者依D.19绘制；组织例均为教学构造，历史文本不替代当代法律核查。"}],"diagramBrief":"当前交付为静态图；交互尚未实现，以下涉及选择、切换或点击的内容仅为后续设计设想。切换内部许可、制度授权和独立规范理由，检验推断是否跨过自己的范围。","applicability":{"realCase":"applicable","diagram":"applicable","reason":"真实原始制度文本提供分项权限阅读对象，不为任何现实政治选择背书，也不把法定人数和通过门槛混同。"},"openQuestions":["未取得19.01—19.08全部思想原著，不解决各传统所有内部争论。","宪法案例只读所列原件转录，不核全部修正、判例、实施史和当代个案适用。"],"taskId":"S-D-19","sources":[{"id":"theory","title":"Xikari-条件结构与转化论，用户提供原文","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"现行全文第4821—4836行；每节精确范围见sourceRefs","claim_support":["D.19：术语、合同、论证责任和原文边界；不据此认证经验事实"],"limits":["作者理论文本，是被解释对象，不替代外部经验资料；技能5.3.1不等于理论版本。"],"access_status":"read"},{"id":"nara-constitution","title":"The Constitution of the United States: A Transcription","url":"https://www.archives.gov/founding-docs/constitution-transcript","source_type":"primary","version_or_date":"原文1787；页面Last reviewed2026-09-08","locator":"Note原件转录说明；Article I Sections1、5、7；页面末reviewed日期","claim_support":["原转录中的立法权、法定人数与复议安排分项存在"],"limits":["只核指定原件转录，未核全修正判例和实施，不从文本存在推整体正当或私人一致同意。"],"access_status":"partially_read"}],"lecturePath":"/reading-assets/S-D-19/lecture.md","sourcesPath":"/reading-assets/S-D-19/sources.json","sourceSlicePath":"/reading-assets/S-D-19/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-D-19/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-d/d-19.md","filePath":"theory/appendix-d/d-19.md"}'),d={name:"theory/appendix-d/d-19.md"};function l(p,e,u,h,f,_){const t=i("SectionLesson");return a(),r("div",null,[e[0]||(e[0]=o('<div class="theory-source"><h1 id="section-d-19" tabindex="-1"><span class="xk-num"><span class="xk-num__n">D.19</span><span class="xk-num__gap">　</span></span>政治思想、制度愿景与规范分歧 <a class="header-anchor" href="#section-d-19" aria-label="Permalink to &quot;D.19　政治思想、制度愿景与规范分歧 {#section-d-19}&quot;">​</a></h1><p>正文连接：§2.2；§14；§16.2、16.15。研究入口：19.01—19.08。</p><p>自由主义、共和主义、民主思想、保守主义、社会主义诸传统、无政府主义、民族主义和去殖民批评，围绕自由、平等、秩序、共同体、财产与权威提出不同问题。比较应准确展示其具体主张、制度机制、适用条件和内部争论，不以框架给政治选择作总排名。</p><p>权利规则、可争辩和可撤换的权力、参与的实际效力、变迁与现状的成本、生产与资源控制、地方协作和跨地域制度，需要分别描述。名义所有、共同身份或地方自治并不直接证明实际控制和分配；一个政治传统关注某项问题，也不说明其他传统完全没有相应考虑。</p><p>愿景可以帮助提出尚未实现的制度可能，反乌托邦可以揭示控制风险；二者均不自动预测历史终点。具体比较需要同一对象、时段和人群，说明谁有何种权利、谁作决定、谁承担过渡成本，以及哪些结果已经观察、哪些仍是条件推论。</p><p>框架自身的authorized、applied及治理状态是其内部承诺，不能冒充外部法律效力或把所有公共决定变成一致同意制度。反过来，存在外部法律依据也不自动证明规范正当。保留这种区分，使思想比较能够提供信息而不替人作政治决定，也不以经验名义消除真正价值冲突。</p><p>稳定、效率与值得维持可以真实分离，不必把规范批评转换成必然失败预言。代表权与分散权力应追踪提名、议题、信息、表决、实施、撤换和复核；一个不可替代关口就可能形成控制，不要求所有环节同时被垄断。合法制度代表并不依赖补造逐人的私人一致同意，仍须面对事项范围和问责。</p><p>专题定位：19.01 自由主义谱系：Locke、Mill、Berlin、Rawls 等；19.02 共和主义与民主思想；19.03 保守主义与传统：Burke 等；19.04 社会主义、马克思主义与社会民主；19.05 无政府主义、互助与地方自治；19.06 民族主义、国家认同与法西斯主义；19.07 后殖民、去殖民与依附理论；19.08 乌托邦、反乌托邦与历史终结叙事。</p></div>',1)),n(t,{section:"D.19"}),e[1]||(e[1]=c("div",{class:"theory-source"},null,-1))])}const x=s(d,[["render",l]]);export{g as __pageData,x as default};
